#ifndef TAPROOT_DRIVER_FIBER_HPP_
#define TAPROOT_DRIVER_FIBER_HPP_

#include <cstddef>
#include <utility>

#include "modm/processing/fiber.hpp"

namespace tap::arch
{
#if defined(ENV_UNIT_TESTS)
// Driver fibers are never started in unit tests, so the stack only has to be valid.
constexpr std::size_t DRIVER_FIBER_STACK_SIZE = 4096;
#elif defined(PLATFORM_HOSTED)
// Hosted fibers need room for the C++ standard library, e.g. iostream.
constexpr std::size_t DRIVER_FIBER_STACK_SIZE = modm::fiber::StackSizeDefault;
#else
// Not measured yet; see the D1 notes on stack sizing.
constexpr std::size_t DRIVER_FIBER_STACK_SIZE = 2048;
#endif

/**
 * A fiber owned by a driver that calls `pollOnce` and then yields, until the fiber is asked to
 * stop. `pollOnce` must not loop forever: it handles whatever data is ready and returns. It may
 * yield internally (e.g. an SPI transfer) while waiting on hardware.
 *
 * The fiber is created stopped. Call `start()` after the driver is initialized and before
 * `modm::fiber::Scheduler::run()`. It does nothing until the scheduler runs.
 *
 * A fiber that was never started is not joinable, so destroying the driver (as every unit test
 * does) returns immediately. Destroying a started fiber requests a stop and waits for the loop to
 * exit, which only happens if the scheduler is running.
 */
template <std::size_t StackSize = DRIVER_FIBER_STACK_SIZE>
class DriverFiber
{
public:
    template <typename PollOnce>
    explicit DriverFiber(PollOnce &&pollOnce)
        : fiber(
              [pollOnce = std::forward<PollOnce>(pollOnce)](modm::fiber::stop_token stop) mutable {
                  while (!stop.stop_requested())
                  {
                      pollOnce();
                      modm::this_fiber::yield();
                  }
              },
              modm::fiber::Start::Later)
    {
    }

    /// Schedules the fiber. Returns `false` if it is already running.
    bool start() { return fiber.start(); }

    /// @return the stack usage measured by the watermark, see `Scheduler::AutoWatermark`.
    std::size_t stackUsage() const { return fiber.stack_usage(); }

private:
    modm::Fiber<StackSize> fiber;
};
}  // namespace tap::arch

#endif  // TAPROOT_DRIVER_FIBER_HPP_
